jsonTools.init:
function init(eli) {
  // ─── Settings registration ──────────────────────────────────────────
  // Three colors only for thin slice — hair STYLE, facial hair, glasses,
  // suit color, etc. wait for the next iteration.
  try {
    if (eli.settings && typeof eli.settings.register === "function") {
      eli.settings.register("mascot.skinTone", {
        default: "#ffdbb5",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "mascotSkinTone" },
        adminPushable: true,
        describe: "ELI mascot skin tone (hex)",
      });
      eli.settings.register("mascot.hairColor", {
        default: "#2d3748",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "mascotHairColor" },
        adminPushable: true,
        describe: "ELI mascot hair color (hex)",
      });
      eli.settings.register("mascot.tieColor", {
        default: "#c62828",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "mascotTieColor" },
        adminPushable: true,
        describe: "ELI mascot tie color (hex)",
      });
    }
  } catch (_e) {}

  // ─── Color palettes ──────────────────────────────────────────────────
  // Skin tones — 8-step spectrum, named for clarity. Hex values picked
  // to read as natural human tones, not random hue jumps.
  var SKIN_TONES = [
    { hex: "#fce4d3", name: "Porcelain" },
    { hex: "#f9d4ae", name: "Fair" },
    { hex: "#ffdbb5", name: "Light" },
    { hex: "#e8b48b", name: "Medium" },
    { hex: "#c89466", name: "Tan" },
    { hex: "#a06d44", name: "Brown" },
    { hex: "#6b4226", name: "Dark Brown" },
    { hex: "#3f2616", name: "Deep" },
  ];
  var HAIR_COLORS = [
    { hex: "#2d3748", name: "Black" },
    { hex: "#5c3317", name: "Dark Brown" },
    { hex: "#8b5a2b", name: "Brown" },
    { hex: "#c19a6b", name: "Blonde" },
    { hex: "#b85c3a", name: "Auburn" },
    { hex: "#a0a0a0", name: "Gray" },
    { hex: "#f5f5f5", name: "White" },
  ];
  var TIE_COLORS = [
    { hex: "#c62828", name: "Red" },
    { hex: "#1565c0", name: "Blue" },
    { hex: "#c9a227", name: "Gold" },
    { hex: "#0d47a1", name: "Navy" },
    { hex: "#2e7d32", name: "Green" },
    { hex: "#6a1b9a", name: "Purple" },
    { hex: "#37474f", name: "Charcoal" },
  ];

  // ─── Tiny utils ──────────────────────────────────────────────────────
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _toast(msg, type) { if (typeof showToast === "function") showToast(msg, type || "info"); }
  function _mount() { return document.getElementById("_eli3_dashboard_root"); }

  // Read current value (saved pref if any, else default). The studio's
  // live-preview state mirrors this on open and tracks edits separately.
  function _getColor(key) {
    try {
      return (eli.settings && eli.settings.get) ? eli.settings.get(key) : null;
    } catch (_e) { return null; }
  }

  // ─── Mascot SVG generator ────────────────────────────────────────────
  // Takes colors, returns SVG markup. Same geometry as ask_eli welcome
  // bubble + eli_kit hero — just with the three fills parameterized.
  // When the kernel helper eli.ui.mascot() lands, THIS function moves
  // into eli_kit and the studio calls it instead.
  function _buildMascotSvg(opts) {
    opts = opts || {};
    var skin = opts.skinTone || "#ffdbb5";
    var hair = opts.hairColor || "#2d3748";
    var tie  = opts.tieColor  || "#c62828";
    // Derive a darker shade of skin for the nose shadow (multiply ~0.92).
    var noseShadow = "#ebbe9b"; // hardcoded for now; could compute later
    return '' +
      '<svg viewBox="0 0 120 120" width="100%" height="100%" class="_eli3_ems_svg">' +
        '<circle cx="60" cy="65" r="45" fill="rgba(147,197,253,0.18)"/>' +
        // Suit
        '<path d="M38,100 C34,110 34,120 34,120 L86,120 C86,120 86,110 82,100 Z" fill="#1565c0"/>' +
        '<path d="M53,100 L67,100 L60,112 Z" fill="#ffffff"/>' +
        // Tie (parameterized)
        '<path d="M58,105 L62,102 L63,120 L57,120 Z" fill="' + tie + '"/>' +
        // Arms
        '<path d="M38,102 Q34,112 34,120" stroke="#1565c0" stroke-width="4.5" fill="none" stroke-linecap="round"/>' +
        '<path d="M82,102 Q86,112 86,120" stroke="#1565c0" stroke-width="4.5" fill="none" stroke-linecap="round"/>' +
        // Head group (animated breathing wrapper would go here once shared)
        '<g class="_eli3_ems_head">' +
          // Neck (parameterized — skin)
          '<rect x="55" y="85" width="10" height="15" rx="2" fill="' + skin + '"/>' +
          // Head base (parameterized — skin)
          '<circle cx="60" cy="72" r="18" fill="' + skin + '"/>' +
          // Hair (parameterized — hair color)
          '<path d="M42,69 C42,52 52,49 60,52 C68,49 78,52 78,69 C78,71 75,58 60,58 C45,58 42,71 42,69 Z" fill="' + hair + '"/>' +
          // Eyes
          '<g class="_eli3_ems_eyes">' +
            '<ellipse cx="52" cy="70" rx="3.5" ry="3.5" fill="#ffffff"/>' +
            '<circle cx="52" cy="70" r="1.8" fill="#1a202c"/>' +
            '<ellipse cx="68" cy="70" rx="3.5" ry="3.5" fill="#ffffff"/>' +
            '<circle cx="68" cy="70" r="1.8" fill="#1a202c"/>' +
          '</g>' +
          // Glasses
          '<circle cx="52" cy="70" r="5.5" fill="rgba(144,202,249,0.15)" stroke="#0d47a1" stroke-width="1.2"/>' +
          '<circle cx="68" cy="70" r="5.5" fill="rgba(144,202,249,0.15)" stroke="#0d47a1" stroke-width="1.2"/>' +
          '<line x1="57" y1="70" x2="63" y2="70" stroke="#0d47a1" stroke-width="1.2"/>' +
          '<line x1="46.5" y1="70" x2="42.5" y2="68" stroke="#0d47a1" stroke-width="1"/>' +
          '<line x1="73.5" y1="70" x2="77.5" y2="68" stroke="#0d47a1" stroke-width="1"/>' +
          // Nose (uses skin-derived shadow)
          '<path d="M60,70 L58.5,75 L61.5,75 Z" fill="' + noseShadow + '"/>' +
          // Smile
          '<path d="M55,81 Q60,85 65,81" stroke="#a04040" stroke-width="1.5" fill="none" stroke-linecap="round"/>' +
        '</g>' +
      '</svg>';
  }

  // ─── Customizer UI ───────────────────────────────────────────────────
  function _showCustomizer() {
    var m = _mount();
    if (!m) { _toast("Dashboard root missing — reload", "err"); return; }
    if (window.eli && window.eli.ui && window.eli.ui.claimOutput) window.eli.ui.claimOutput();
    m.style.display = "";
    m.innerHTML = "";

    // Live-edit state — initialized from current saved/default values.
    var state = {
      skinTone:  _getColor("mascot.skinTone")  || SKIN_TONES[2].hex,
      hairColor: _getColor("mascot.hairColor") || HAIR_COLORS[0].hex,
      tieColor:  _getColor("mascot.tieColor")  || TIE_COLORS[0].hex,
    };

    // Shell — full-area takeover like Settings.
    var root = document.createElement("div");
    root.className = "_eli3_ems_root";
    root.innerHTML =
      '<div class="_eli3_ems_header">' +
        '<button data-act="back" class="_eli3_ems_back" title="Back to dashboard">←</button>' +
        '<div class="_eli3_ems_title">Personalize ELI</div>' +
      '</div>' +
      '<div class="_eli3_ems_body">' +
        // Live preview
        '<div class="_eli3_ems_preview">' +
          '<div class="_eli3_ems_glow" aria-hidden="true"></div>' +
          '<div class="_eli3_ems_mascot_wrap" data-slot="mascot"></div>' +
          '<div class="_eli3_ems_preview_label">Live preview</div>' +
        '</div>' +
        // Controls
        '<div class="_eli3_ems_controls">' +
          _renderSwatchRow("Skin tone", "skinTone", SKIN_TONES, state.skinTone) +
          _renderSwatchRow("Hair color", "hairColor", HAIR_COLORS, state.hairColor) +
          _renderSwatchRow("Tie color", "tieColor", TIE_COLORS, state.tieColor) +
        '</div>' +
        // Footer actions
        '<div class="_eli3_ems_footer">' +
          '<button data-act="reset" class="_eli3_ems_btn _eli3_ems_btn_secondary" title="Restore default appearance">↺ Reset to default</button>' +
          '<div style="flex:1"></div>' +
          '<button data-act="cancel" class="_eli3_ems_btn _eli3_ems_btn_secondary">Cancel</button>' +
          '<button data-act="save" class="_eli3_ems_btn _eli3_ems_btn_primary">💾 Save</button>' +
        '</div>' +
      '</div>';
    m.appendChild(root);

    var mascotSlot = root.querySelector("[data-slot='mascot']");
    function _repaintMascot() {
      mascotSlot.innerHTML = _buildMascotSvg(state);
    }
    _repaintMascot();

    // Wire swatch clicks — clicking updates state and re-paints preview.
    root.querySelectorAll("[data-swatch]").forEach(function (el) {
      el.onclick = function () {
        var key = el.getAttribute("data-key");
        var hex = el.getAttribute("data-swatch");
        state[key] = hex;
        // Update visual "selected" ring
        root.querySelectorAll('[data-key="' + key + '"]').forEach(function (sib) {
          sib.classList.toggle("_eli3_ems_swatch_selected", sib.getAttribute("data-swatch") === hex);
        });
        _repaintMascot();
      };
    });

    root.querySelector("[data-act='back']").onclick = _goHome;
    root.querySelector("[data-act='cancel']").onclick = _goHome;
    root.querySelector("[data-act='reset']").onclick = function () {
      state.skinTone  = SKIN_TONES[2].hex;
      state.hairColor = HAIR_COLORS[0].hex;
      state.tieColor  = TIE_COLORS[0].hex;
      // Refresh selected rings
      [["skinTone", state.skinTone], ["hairColor", state.hairColor], ["tieColor", state.tieColor]]
        .forEach(function (pair) {
          root.querySelectorAll('[data-key="' + pair[0] + '"]').forEach(function (sib) {
            sib.classList.toggle("_eli3_ems_swatch_selected", sib.getAttribute("data-swatch") === pair[1]);
          });
        });
      _repaintMascot();
      _toast("Preview reset to default — click Save to apply.", "info");
    };
    root.querySelector("[data-act='save']").onclick = function () {
      try {
        var layer = (eli.settings && eli.settings.LAYER_USER) || "user";
        eli.settings.set("mascot.skinTone",  state.skinTone,  { layer: layer });
        eli.settings.set("mascot.hairColor", state.hairColor, { layer: layer });
        eli.settings.set("mascot.tieColor",  state.tieColor,  { layer: layer });
        // Bus event so future ask_eli / eli_kit listeners can repaint.
        try { eli.bus.emit("mascot:customized", { state: state }); } catch (_e) {}
        _toast("✅ ELI updated.", "ok");
        // Record open/save in stats so we can see usage.
        try { eli.stats.record("appOpenedMascotStudio"); } catch (_) {}
      } catch (err) {
        _toast("Save failed: " + (err && err.message), "err");
      }
    };
  }

  function _renderSwatchRow(label, key, palette, currentHex) {
    return '<div class="_eli3_ems_row">' +
      '<div class="_eli3_ems_row_label">' + _esc(label) + '</div>' +
      '<div class="_eli3_ems_swatches">' +
        palette.map(function (sw) {
          var selected = sw.hex.toLowerCase() === String(currentHex || "").toLowerCase();
          return '<button class="_eli3_ems_swatch' + (selected ? ' _eli3_ems_swatch_selected' : '') + '"' +
            ' data-key="' + _esc(key) + '" data-swatch="' + _esc(sw.hex) + '"' +
            ' style="background:' + _esc(sw.hex) + ';"' +
            ' title="' + _esc(sw.name) + '">' +
            '</button>';
        }).join("") +
      '</div>' +
    '</div>';
  }

  function _goHome() {
    if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
  }

  // ─── Inject styles once ──────────────────────────────────────────────
  // No bundle.css today — small enough to inline. When eli.ui.mascot()
  // lands in eli_kit, mascot animation CSS centralizes there.
  if (!document.getElementById("_eli3_ems_style")) {
    var s = document.createElement("style");
    s.id = "_eli3_ems_style";
    s.textContent =
      '._eli3_ems_root{background:#f1f5f9;min-height:100%;font:500 13px/1.45 \'Inter\',\'Segoe UI\',sans-serif;color:#0f172a;}' +
      '._eli3_ems_header{background:linear-gradient(180deg,#fff,#f8fafc);border-bottom:1px solid #e2e8f0;padding:14px 20px;display:flex;align-items:center;gap:12px;position:sticky;top:0;z-index:5;}' +
      '._eli3_ems_back{border:1px solid #e2e8f0;background:#fff;border-radius:6px;padding:4px 10px;cursor:pointer;font-size:14px;color:#475569;}' +
      '._eli3_ems_title{font:700 15px/1 \'Inter\',sans-serif;color:#0f172a;}' +
      '._eli3_ems_body{padding:28px 32px;max-width:680px;margin:0 auto;}' +
      '._eli3_ems_preview{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px 0 16px;margin-bottom:24px;}' +
      '._eli3_ems_glow{position:absolute;top:10px;left:50%;transform:translateX(-50%);width:200px;height:200px;border-radius:50%;background:radial-gradient(circle at 50% 45%,rgba(253,224,71,0.20) 0%,rgba(147,197,253,0.16) 35%,transparent 70%);animation:_eli3_ems_glow_pulse 3.2s ease-in-out infinite;pointer-events:none;z-index:0;}' +
      '@keyframes _eli3_ems_glow_pulse{0%,100%{opacity:0.7;transform:translateX(-50%) scale(1);}50%{opacity:1;transform:translateX(-50%) scale(1.08);}}' +
      '._eli3_ems_mascot_wrap{position:relative;z-index:1;width:160px;height:200px;display:flex;align-items:flex-end;justify-content:center;filter:drop-shadow(0 6px 14px rgba(13,71,161,0.35)) drop-shadow(0 2px 4px rgba(0,0,0,0.18));}' +
      '._eli3_ems_svg{display:block;animation:_eli3_ems_breathe 1.8s ease-in-out infinite alternate;transform-origin:center bottom;}' +
      '._eli3_ems_svg ._eli3_ems_head{animation:_eli3_ems_head_bob 1.8s ease-in-out infinite alternate;transform-origin:60px 85px;}' +
      '@keyframes _eli3_ems_breathe{0%{transform:scale(1);}100%{transform:scale(1.02);}}' +
      '@keyframes _eli3_ems_head_bob{0%{transform:translateY(0);}100%{transform:translateY(-2px);}}' +
      '._eli3_ems_preview_label{margin-top:14px;font:600 10px/1 \'Inter\',sans-serif;color:#94a3b8;text-transform:uppercase;letter-spacing:1.5px;}' +
      '._eli3_ems_controls{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px 20px;box-shadow:0 1px 2px rgba(15,23,42,0.04);}' +
      '._eli3_ems_row{padding:14px 0;border-top:1px solid #f1f5f9;}' +
      '._eli3_ems_row:first-child{border-top:none;padding-top:0;}' +
      '._eli3_ems_row:last-child{padding-bottom:0;}' +
      '._eli3_ems_row_label{font:700 11px/1 \'Inter\',sans-serif;color:#475569;text-transform:uppercase;letter-spacing:0.8px;margin-bottom:10px;}' +
      '._eli3_ems_swatches{display:flex;flex-wrap:wrap;gap:8px;}' +
      '._eli3_ems_swatch{width:34px;height:34px;border-radius:50%;border:2px solid transparent;cursor:pointer;padding:0;box-shadow:0 1px 2px rgba(0,0,0,0.12),inset 0 1px 2px rgba(255,255,255,0.25);transition:transform 0.15s ease,border-color 0.15s ease;}' +
      '._eli3_ems_swatch:hover{transform:scale(1.08);}' +
      '._eli3_ems_swatch_selected{border-color:#1565c0;box-shadow:0 0 0 2px #fff inset,0 0 0 4px #1565c0,0 2px 4px rgba(0,0,0,0.15);transform:scale(1.05);}' +
      '._eli3_ems_footer{display:flex;align-items:center;gap:10px;margin-top:22px;}' +
      '._eli3_ems_btn{border-radius:6px;padding:8px 16px;font:600 13px/1 \'Inter\',sans-serif;cursor:pointer;border:1px solid;transition:all 0.15s ease;}' +
      '._eli3_ems_btn_secondary{background:linear-gradient(180deg,#fff,#f1f5f9);color:#334155;border-color:#cbd5e1;}' +
      '._eli3_ems_btn_secondary:hover{background:linear-gradient(180deg,#f8fafc,#e2e8f0);}' +
      '._eli3_ems_btn_primary{background:linear-gradient(180deg,#2563eb,#1d4ed8);color:#fff;border-color:#1d4ed8;box-shadow:0 1px 2px rgba(29,78,216,0.3);}' +
      '._eli3_ems_btn_primary:hover{background:linear-gradient(180deg,#1d4ed8,#1e40af);}';
    document.head.appendChild(s);
  }

  // ─── Self-register tile handler ──────────────────────────────────────
  eli.register({ tile: { app_eli_mascot_studio: _showCustomizer } });

  // Optional: expose builder for inspection / future tools.
  // (Not part of public API yet — will move to eli.ui.mascot in next step.)
  if (window.eli) {
    window.eli._mascotPreview = _buildMascotSvg;
  }

  eli.log.event("tool", "eli_mascot_studio_initialized", {});
}
